export * as PreviewCard from './preview-card.tsx';
export type {
  ContentOwnProps as PreviewCardContentOwnProps,
  ContentProps as PreviewCardContentProps,
} from './preview-card.tsx';

@layer hj.components {
  /* Customise: --hj-preview-card-width · --hj-preview-card-radius */
  .hj-preview-card-trigger {
    color: var(--hj-fg);
    font-weight: 600;
    text-decoration: underline;
    text-decoration-color: color-mix(in srgb, var(--hj-fg) 30%, transparent);
    text-decoration-thickness: 1px;
    text-underline-offset: 3px;
    transition: text-decoration-color var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-preview-card-trigger:hover,
  .hj-preview-card-trigger[data-popup-open] {
    text-decoration-color: var(--hj-accent);
  }
  .hj-preview-card-positioner {
    z-index: var(--hj-z-popover);
  }
  .hj-preview-card-backdrop {
    position: fixed;
    inset: 0;
  }

  .hj-preview-card-popup {
    position: relative;
    width: min(var(--hj-preview-card-width, 300px), var(--available-width, 100vw));
    border: 1px solid var(--hj-line);
    border-radius: var(--hj-preview-card-radius, var(--hj-radius-md));
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface-2);
    box-shadow: var(--hj-shadow-lift);
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    transform-origin: var(--transform-origin);
    transition:
      transform var(--hj-dur-snappy) var(--hj-ease-snappy),
      opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-preview-card-popup[data-starting-style],
  .hj-preview-card-popup[data-ending-style] {
    opacity: 0;
    transform: scale(0.94);
  }
  .hj-preview-card-popup[data-ending-style] {
    transition-duration: var(--hj-dur-fast);
    transition-timing-function: var(--hj-ease-out);
  }
  .hj-preview-card-popup[data-instant] {
    transition: none;
  }
  .hj-preview-card-viewport {
    position: relative;
    overflow: clip;
    border-radius: inherit;
    corner-shape: inherit;
  }

  .hj-preview-card-media {
    aspect-ratio: 16 / 9;
    overflow: hidden;
    border-radius: calc(var(--hj-preview-card-radius, var(--hj-radius-md)) - 1px)
      calc(var(--hj-preview-card-radius, var(--hj-radius-md)) - 1px) 0 0;
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface);
  }
  .hj-preview-card-media > img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
  }
  .hj-preview-card-body {
    display: flex;
    flex-direction: column;
    gap: calc(4px * var(--hj-density));
    padding: calc(14px * var(--hj-density)) calc(16px * var(--hj-density))
      calc(16px * var(--hj-density));
  }
  .hj-preview-card-title {
    margin: 0;
    font: var(--hj-type-heading);
    letter-spacing: var(--hj-tracking-heading);
  }
  .hj-preview-card-description {
    margin: 0;
    font-size: 13px;
    line-height: 1.5;
    color: var(--hj-fg-dim);
  }

  .hj-preview-card-arrow {
    position: relative;
    display: block;
    width: 14px;
    height: 7px;
    overflow: clip;
  }
  .hj-preview-card-arrow[data-side='top'] {
    bottom: -7px;
    rotate: 180deg;
  }
  .hj-preview-card-arrow[data-side='bottom'] {
    top: -7px;
  }
  .hj-preview-card-arrow[data-side='left'] {
    right: -10px;
    rotate: 90deg;
  }
  .hj-preview-card-arrow[data-side='right'] {
    left: -10px;
    rotate: -90deg;
  }
  .hj-preview-card-arrow::before {
    content: '';
    position: absolute;
    bottom: 0;
    left: 50%;
    width: 10px;
    height: 10px;
    border: 1px solid var(--hj-line);
    background: var(--hj-surface-2);
    transform: translate(-50%, 50%) rotate(45deg);
  }
}

'use client';
import { PreviewCard as Base } from '@base-ui/react/preview-card';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart, part } from '../../system/part.tsx';
import type { ElementPartProps, HanjiPart } from '../../system/part.tsx';
import { withDefaults } from '../../system/slot.ts';
import { ThemeScope } from '../../system/theme.tsx';

export const Root: typeof Base.Root = Base.Root;
/** A link that previews where it goes on hover or focus. Renders an `<a>`. */
export const Trigger: HanjiPart<typeof Base.Trigger> = part(
  Base.Trigger,
  'PreviewCard.Trigger',
  'hj-preview-card-trigger',
);
export const Positioner: HanjiPart<typeof Base.Positioner> = part(
  Base.Positioner,
  'PreviewCard.Positioner',
  'hj-preview-card-positioner',
);
export const Popup: HanjiPart<typeof Base.Popup> = part(
  Base.Popup,
  'PreviewCard.Popup',
  'hj-preview-card-popup',
);
export const Arrow: HanjiPart<typeof Base.Arrow> = part(
  Base.Arrow,
  'PreviewCard.Arrow',
  'hj-preview-card-arrow',
);
export const Backdrop: HanjiPart<typeof Base.Backdrop> = part(
  Base.Backdrop,
  'PreviewCard.Backdrop',
  'hj-preview-card-backdrop',
);
export const Viewport: HanjiPart<typeof Base.Viewport> = part(
  Base.Viewport,
  'PreviewCard.Viewport',
  'hj-preview-card-viewport',
);
/** Full-bleed image or art at the top of the card. */
export const Media: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'PreviewCard.Media',
  'hj-preview-card-media',
);
/** The padded text area under the media. */
export const Body: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'PreviewCard.Body',
  'hj-preview-card-body',
);
export const Title: (props: ElementPartProps<'p'>) => React.ReactElement = elementPart(
  'p',
  'PreviewCard.Title',
  'hj-preview-card-title',
);
export const Description: (props: ElementPartProps<'p'>) => React.ReactElement = elementPart(
  'p',
  'PreviewCard.Description',
  'hj-preview-card-description',
);
export const createHandle: typeof Base.createHandle = Base.createHandle;

/** Portals to `<body>` but keeps the nearest `<Theme>`. */
export function Portal({ children, ...props }: Base.Portal.Props): React.ReactElement {
  return (
    <Base.Portal {...props}>
      <ThemeScope>{children}</ThemeScope>
    </Base.Portal>
  );
}

export interface ContentOwnProps {
  side?: Base.Positioner.Props['side'];
  align?: Base.Positioner.Props['align'];
  /** Gap from the link in px. @default 8 */
  sideOffset?: Base.Positioner.Props['sideOffset'];
  /** Draw the arrow. @default false */
  arrow?: boolean;
  container?: Base.Portal.Props['container'];
}
export interface ContentProps extends ContentOwnProps, Base.Popup.Props {}

/** Shorthand for Portal + Positioner + Popup (+ Arrow). */
export function Content(props: ContentProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    side = 'bottom',
    align,
    sideOffset = 8,
    arrow = false,
    container,
    children,
    ...popup
  } = withDefaults(config, 'PreviewCard.Content', props);
  return (
    <Portal container={container}>
      <Positioner side={side} align={align} sideOffset={sideOffset} collisionPadding={8}>
        <Popup {...popup}>
          {arrow ? <Arrow /> : null}
          {children}
        </Popup>
      </Positioner>
    </Portal>
  );
}
